//! Scheduled profiles (AUT-02). Owner: W3-E. Stored in `<data>/schedules.json`.
//!
//! A schedule is a name, a scope, a recurrence and a list of step templates.
//! **Only steps that need no confirmation may be scheduled** (SAF-11): lossy,
//! permanent and review-only steps are rejected at save time, because a job that
//! runs while nobody is looking must be reversible. `next_run` is recomputed on
//! every save and list (see [`next`]). The OS registration (Task Scheduler,
//! systemd user timer) is generated by [`os`] and installed only on an explicit
//! user action; the engine itself never registers anything.

pub mod next;
pub mod os;

use std::sync::Arc;

use mj_core::{lock, Error, Result, Schedule, ScheduledStep, SettingKind, Timestamp};

use crate::api::{
    ApplyStarted, IdRequest, PlanAddStepRequest, PlanApplyRequest, ScanRunState, ScanStartRequest,
    ScheduleFromPlanRequest, ScheduleSaveRequest, ScopeSetRequest,
};
use crate::settings::persist::{read_or_backup, Loaded};
use crate::Engine;

const FILE: &str = "schedules.json";

pub(crate) fn load(engine: &Engine) {
    if !engine.cfg.persist {
        return;
    }
    if let Loaded::Ok(v) = read_or_backup::<Vec<Schedule>>(&engine.cfg.data_dir.join(FILE)) {
        *lock(&engine.schedules) = v;
    }
}

/// True when running `step` would be lossy: the optimiser is lossy by nature, a
/// lossy toggle is on, or the parameters carry every value of a lossy preset.
fn step_is_lossy(engine: &Engine, step: &ScheduledStep) -> bool {
    let mj_core::Action::Optimise { optimiser, params, .. } = &step.action else { return false };
    let Some(info) = engine.optimisers.iter().map(|o| o.info()).find(|i| &i.id == optimiser) else { return false };
    if info.safety == mj_core::SafetyClass::LossyOptIn {
        return true;
    }
    let merged = step.params.merged(params);
    let toggled = info
        .settings
        .iter()
        .any(|s| s.lossy && matches!(s.kind, SettingKind::Toggle { .. }) && merged.bool(&s.key, false));
    let preset = info
        .presets
        .iter()
        .any(|p| p.lossy && !p.values.0.is_empty() && p.values.0.iter().all(|(k, v)| merged.0.get(k) == Some(v)));
    toggled || preset
}

/// Check a schedule before it is stored.
fn validate(engine: &Engine, s: &Schedule) -> Result<()> {
    if s.name.trim().is_empty() {
        return Err(Error::InvalidInput("a schedule needs a name".into()));
    }
    next::validate_cadence(&s.cadence)?;
    if s.scope.roots.is_empty() {
        return Err(Error::InvalidInput("a schedule needs at least one folder to scan".into()));
    }
    if let Some(r) = s.scope.roots.iter().find(|r| !r.is_absolute()) {
        return Err(Error::InvalidInput(format!("schedule folders must be absolute paths: {}", r.display())));
    }
    if s.steps.is_empty() {
        return Err(Error::InvalidInput("a schedule needs at least one step".into()));
    }
    for step in &s.steps {
        let reason = if matches!(step.action, mj_core::Action::None) {
            Some("review-only steps do nothing")
        } else if step.action.safety(false).requires_confirmation() || step_is_lossy(engine, step) {
            Some("lossy or permanent steps cannot run unattended")
        } else {
            None
        };
        if let Some(r) = reason {
            return Err(Error::InvalidInput(format!("step {}: {r}", step.opportunity.0)));
        }
    }
    Ok(())
}

/// `sched_<n>` with `n` above every existing one (ids must survive restarts).
fn fresh_id(existing: &[Schedule]) -> String {
    let max = existing.iter().filter_map(|s| s.id.strip_prefix("sched_")?.parse::<u64>().ok()).max().unwrap_or(0);
    format!("sched_{}", max + 1)
}

impl Engine {
    fn save_schedules(&self) -> Result<()> {
        if self.cfg.persist {
            crate::store::write_json(&self.cfg.data_dir.join(FILE), &*lock(&self.schedules))?;
        }
        Ok(())
    }

    fn with_next_run(s: &Schedule, now: Timestamp) -> Schedule {
        let mut s = s.clone();
        s.next_run = s.enabled.then(|| next::next_run(&s.cadence, now, next::local_offset_minutes()));
        s
    }

    /// Schedules, with `next_run` computed from now.
    pub fn schedules_list(&self) -> Result<Vec<Schedule>> {
        let now = Timestamp::now();
        Ok(lock(&self.schedules).iter().map(|s| Self::with_next_run(s, now)).collect())
    }

    /// Enabled schedules whose next run after their last run (or creation) is at or before `now`.
    /// The shell may poll this to run profiles while the app is open.
    pub fn schedules_due(&self, now: Timestamp, since: Timestamp) -> Vec<Schedule> {
        let off = next::local_offset_minutes();
        lock(&self.schedules)
            .iter()
            .filter(|s| s.enabled && next::next_run(&s.cadence, s.last_run.unwrap_or(since), off) <= now)
            .cloned()
            .collect()
    }

    /// Insert or replace a schedule.
    pub fn schedule_save(&self, req: ScheduleSaveRequest) -> Result<Vec<Schedule>> {
        let mut s = req.schedule;
        s.name = s.name.trim().to_string();
        validate(self, &s)?;
        {
            let mut v = lock(&self.schedules);
            if v.iter().any(|x| x.id != s.id && x.name.to_lowercase() == s.name.to_lowercase()) {
                return Err(Error::InvalidInput(format!("a schedule named \"{}\" already exists", s.name)));
            }
            if s.id.is_empty() {
                s.id = fresh_id(&v);
            }
            match v.iter_mut().find(|x| x.id == s.id) {
                Some(slot) => *slot = s,
                None => v.push(s),
            }
        }
        self.save_schedules()?;
        self.schedules_list()
    }

    /// Delete a schedule (an OS registration, if any, is removed by the caller: `schedule uninstall`).
    pub fn schedule_delete(&self, req: IdRequest) -> Result<Vec<Schedule>> {
        {
            let mut v = lock(&self.schedules);
            let before = v.len();
            v.retain(|s| s.id != req.id);
            if v.len() == before {
                return Err(Error::InvalidInput(format!("no schedule with id {}", req.id)));
            }
        }
        self.save_schedules()?;
        self.schedules_list()
    }

    /// "Save as weekly schedule" from the current plan and scope.
    pub fn schedule_from_plan(&self, req: ScheduleFromPlanRequest) -> Result<Schedule> {
        let plan = lock(&self.plan).plan.clone();
        if plan.steps.is_empty() {
            return Err(Error::InvalidInput("the plan is empty".into()));
        }
        if plan.steps.iter().any(|s| s.safety.requires_confirmation()) {
            return Err(Error::InvalidInput(
                "lossy or permanent steps cannot run unattended; remove them first".into(),
            ));
        }
        let schedule = Schedule {
            id: String::new(),
            name: req.name,
            enabled: true,
            cadence: req.cadence,
            scope: lock(&self.scope).clone(),
            steps: plan
                .steps
                .iter()
                .map(|s| ScheduledStep {
                    opportunity: s.opportunity.clone(),
                    action: s.action.clone(),
                    params: s.params.clone(),
                })
                .collect(),
            last_run: None,
            next_run: None,
        };
        let name = schedule.name.trim().to_lowercase();
        let list = self.schedule_save(ScheduleSaveRequest { schedule })?;
        list.into_iter()
            .find(|s| s.name.to_lowercase() == name)
            .ok_or_else(|| Error::Internal("schedule not stored".into()))
    }

    /// Run a schedule now: scan its scope, add its steps with default selections and apply.
    ///
    /// Blocks until the scan is done (the shell calls it off the UI thread), then
    /// returns as soon as the apply jobs are queued. Refuses when a plan is in
    /// progress (the session plan is the only one there is). Steps whose
    /// opportunity was not found this time are skipped; with nothing left the
    /// error message starts with `nothing to do`.
    pub fn schedule_run_now(self: &Arc<Self>, req: IdRequest) -> Result<ApplyStarted> {
        let sched = lock(&self.schedules)
            .iter()
            .find(|s| s.id == req.id)
            .cloned()
            .ok_or_else(|| Error::InvalidInput(format!("unknown schedule {}", req.id)))?;
        validate(self, &sched)?;
        if !lock(&self.plan).plan.steps.is_empty() {
            return Err(Error::Conflict("a plan is in progress: apply or clear it before running a schedule".into()));
        }
        self.scope_set(ScopeSetRequest { scope: sched.scope.clone() })?;
        self.scan_start(ScanStartRequest::default())?;
        loop {
            let st = self.scan_status()?;
            match st.state {
                ScanRunState::Scanning | ScanRunState::Paused | ScanRunState::Stopping => {
                    std::thread::sleep(std::time::Duration::from_millis(50))
                }
                ScanRunState::Done => break,
                other => {
                    let why = st.error.map(|e| e.message).unwrap_or_else(|| format!("scan ended as {other:?}"));
                    return Err(Error::Internal(format!("the scan for \"{}\" did not finish: {why}", sched.name)));
                }
            }
        }
        let started = self.apply_steps(&sched);
        if started.is_err() {
            let _ = self.plan_clear();
        }
        let started = started?;
        {
            let mut v = lock(&self.schedules);
            if let Some(s) = v.iter_mut().find(|s| s.id == sched.id) {
                s.last_run = Some(Timestamp::now());
            }
        }
        self.save_schedules()?;
        Ok(started)
    }

    fn apply_steps(self: &Arc<Self>, sched: &Schedule) -> Result<ApplyStarted> {
        let mut skipped = 0;
        for step in &sched.steps {
            let added = self.plan_add_step(PlanAddStepRequest {
                opportunity_id: step.opportunity.clone(),
                action: Some(step.action.clone()),
                params: Some(step.params.clone()),
            });
            match added {
                Ok(_) => {}
                Err(Error::InvalidInput(_) | Error::Unsupported { .. } | Error::Conflict(_)) => skipped += 1,
                Err(e) => return Err(e),
            }
        }
        let plan = lock(&self.plan).plan.clone();
        if plan.steps.is_empty() {
            return Err(Error::InvalidInput(format!(
                "nothing to do: none of the {skipped} steps found anything this time"
            )));
        }
        // Defence in depth: the opportunity may be lossier than the template said.
        if plan.steps.iter().any(|s| s.safety.requires_confirmation()) {
            return Err(Error::ConfirmationRequired(
                "a scheduled step turned out to need confirmation; it was not run".into(),
            ));
        }
        self.plan_apply(PlanApplyRequest::default())
    }
}

#[cfg(test)]
mod tests {
    use mj_core::testutil::TempDir;
    use mj_core::{Action, Cadence, OpportunityId, OriginalsPolicy, OutputMode, ParamValue, ParamValues, ScanScope};

    use super::*;
    use crate::{Engine, EngineConfig};

    fn engine_in(t: &TempDir) -> Arc<Engine> {
        Engine::new(EngineConfig::new(t.join("data"), t.join("cache"))).unwrap()
    }

    fn abs(s: &str) -> std::path::PathBuf {
        if cfg!(windows) {
            std::path::PathBuf::from(format!("C:\\{s}"))
        } else {
            std::path::PathBuf::from(format!("/{s}"))
        }
    }

    fn step(id: &str, action: Action) -> ScheduledStep {
        ScheduledStep { opportunity: OpportunityId(id.into()), action, params: ParamValues::new() }
    }

    fn sched(name: &str, steps: Vec<ScheduledStep>) -> Schedule {
        Schedule {
            id: String::new(),
            name: name.into(),
            enabled: true,
            cadence: Cadence::Weekly { weekday: 1, hour: 8, minute: 47 },
            scope: ScanScope { roots: vec![abs("home/m/Downloads")], ..ScanScope::default() },
            steps,
            last_run: None,
            next_run: None,
        }
    }

    fn save(e: &Engine, s: Schedule) -> Result<Vec<Schedule>> {
        e.schedule_save(ScheduleSaveRequest { schedule: s })
    }

    #[test]
    fn saves_persists_and_computes_next_run() {
        let t = TempDir::new("sched-save").unwrap();
        let e = engine_in(&t);
        let list = save(&e, sched("Weekly Downloads", vec![step("det:temp_files", Action::Trash)])).unwrap();
        assert_eq!(list[0].id, "sched_1");
        assert!(list[0].next_run.unwrap() > Timestamp::now());
        let again = engine_in(&t);
        assert_eq!(again.schedules_list().unwrap().len(), 1);
        // New ids continue after a restart instead of colliding.
        let list = save(&again, sched("Second", vec![step("det:temp_files", Action::Trash)])).unwrap();
        assert_eq!(list[1].id, "sched_2");
        // Disabled schedules have no next run.
        let mut off = list[1].clone();
        off.enabled = false;
        assert_eq!(save(&again, off).unwrap()[1].next_run, None);
    }

    #[test]
    fn only_reversible_steps_are_accepted() {
        let t = TempDir::new("sched-rev").unwrap();
        let e = engine_in(&t);
        let err = |a: Action| save(&e, sched("x", vec![step("det:a", a)])).unwrap_err();
        assert!(err(Action::PermanentDelete).to_string().contains("unattended"));
        assert!(err(Action::None).to_string().contains("review-only"));
        let delete_originals = Action::Optimise {
            optimiser: mj_core::optimiser::OptimiserId::Audio,
            params: ParamValues::new(),
            output: OutputMode::Replace,
            originals: OriginalsPolicy::Delete,
            keep_if_not_smaller: true,
        };
        assert!(err(delete_originals).to_string().contains("unattended"));
        let archive_delete = Action::Archive {
            format: mj_core::ArchiveFormat::Zip,
            level: 6,
            dest: None,
            originals: OriginalsPolicy::Delete,
            keep_sources: false,
        };
        assert!(err(archive_delete).to_string().contains("unattended"));
        for ok in [
            Action::Trash,
            Action::Quarantine { purge_after_days: 30 },
            Action::Hardlink,
            Action::Move { dest: abs("backup"), keep_structure: true },
        ] {
            assert!(save(&e, sched(&format!("ok {ok:?}"), vec![step("det:a", ok)])).is_ok());
        }
    }

    #[test]
    fn lossy_optimisers_are_detected_through_their_info() {
        let t = TempDir::new("sched-lossy").unwrap();
        let e = engine_in(&t);
        let lossy = e.optimisers.iter().map(|o| o.info()).find(|i| i.safety == mj_core::SafetyClass::LossyOptIn);
        let Some(info) = lossy else { return };
        let a = Action::Optimise {
            optimiser: info.id,
            params: ParamValues::new().with("x", ParamValue::Bool(true)),
            output: OutputMode::Replace,
            originals: OriginalsPolicy::RecycleBin,
            keep_if_not_smaller: true,
        };
        assert!(save(&e, sched("lossy", vec![step("opt:x", a)])).is_err());
    }

    #[test]
    fn structural_validation() {
        let t = TempDir::new("sched-val").unwrap();
        let e = engine_in(&t);
        let ok = || sched("A", vec![step("det:a", Action::Trash)]);
        let mut s = ok();
        s.name = "  ".into();
        assert!(save(&e, s).is_err());
        let mut s = ok();
        s.steps.clear();
        assert!(save(&e, s).is_err());
        let mut s = ok();
        s.scope.roots.clear();
        assert!(save(&e, s).is_err());
        let mut s = ok();
        s.scope.roots = vec![std::path::PathBuf::from("rel")];
        assert!(save(&e, s).is_err());
        let mut s = ok();
        s.cadence = Cadence::Monthly { day: 31, hour: 1, minute: 0 };
        assert!(save(&e, s).is_err());
        save(&e, ok()).unwrap();
        assert!(save(&e, sched("a", vec![step("det:a", Action::Trash)]))
            .unwrap_err()
            .to_string()
            .contains("already exists"));
    }

    #[test]
    fn delete_removes_only_the_named_schedule() {
        let t = TempDir::new("sched-del").unwrap();
        let e = engine_in(&t);
        save(&e, sched("A", vec![step("det:a", Action::Trash)])).unwrap();
        let list = save(&e, sched("B", vec![step("det:a", Action::Trash)])).unwrap();
        assert!(e.schedule_delete(IdRequest { id: "sched_9".into() }).is_err());
        let left = e.schedule_delete(IdRequest { id: list[0].id.clone() }).unwrap();
        assert_eq!(left.len(), 1);
        assert_eq!(left[0].name, "B");
    }

    #[test]
    fn from_plan_rejects_an_empty_plan() {
        let t = TempDir::new("sched-plan").unwrap();
        let e = engine_in(&t);
        let r = e.schedule_from_plan(ScheduleFromPlanRequest {
            name: "W".into(),
            cadence: Cadence::Daily { hour: 1, minute: 0 },
        });
        assert_eq!(r.unwrap_err().code(), "invalid_input");
    }

    #[test]
    fn due_schedules_follow_last_run() {
        let t = TempDir::new("sched-due").unwrap();
        let e = engine_in(&t);
        let mut s = sched("D", vec![step("det:a", Action::Trash)]);
        s.cadence = Cadence::Daily { hour: 3, minute: 0 };
        save(&e, s).unwrap();
        let now = Timestamp::now();
        assert!(e.schedules_due(now, now).is_empty());
        let long_ago = now.add_days(-3);
        assert_eq!(e.schedules_due(now, long_ago).len(), 1);
    }

    #[test]
    fn corrupt_schedules_file_is_backed_up() {
        let t = TempDir::new("sched-corrupt").unwrap();
        std::fs::create_dir_all(t.join("data")).unwrap();
        std::fs::write(t.join("data/schedules.json"), b"[[").unwrap();
        assert!(engine_in(&t).schedules_list().unwrap().is_empty());
        assert!(std::fs::read_dir(t.join("data"))
            .unwrap()
            .filter_map(|d| d.ok())
            .any(|d| d.file_name().to_string_lossy().starts_with("schedules.json.bad-")));
    }
}
